import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs';
import {NativeHomeSession} from '../native_home_entries_remaining_1524/session.mjs';
const root=new URL('../native_home_entries_remaining_1524/',import.meta.url),c=JSON.parse(fs.readFileSync(new URL('contract.json',root))),masks=Object.fromEntries(Object.entries(c.masks).map(([k,v])=>[k,new Uint8Array(fs.readFileSync(new URL(v.path,root)))]));
const make=(loader)=>new NativeHomeSession({contract:c,homeId:'upper',masks,...(loader?{loadScene:loader}:{})});
const at=(s,id)=>{s.foot=[...c.houses[id].exteriorDoor.readFoot];s.face('up');s.releaseAction()};
test('cancelled old different-home rejection cannot cancel newer valid home transaction',async()=>{let rejectOld,resolveNew,n=0;const s=make(()=>new Promise((r,j)=>{if(!n++)rejectOld=j;else resolveNew=r}));s.setDoorState('OPEN','coastal');at(s,'coastal');const old=s.action();s.cancel();s.move('down');s.move('up');s.releaseAction();const newer=s.action();rejectOld(Error('late'));assert.equal((await old).reason,'STALE');assert.equal(s.pending,true);assert.equal(s.homeId,'upper');resolveNew({sha256:c.sources.coastal_1F.sha256});assert.equal((await newer).ok,true);assert.equal(s.homeId,'coastal');assert.equal(s.pending,false)});
test('home switch preserves other door lock and outside support mask exactly',async()=>{const s=make();s.setDoorState('OPEN','coastal');at(s,'coastal');assert.equal((await s.action()).ok,true);assert.equal(s.doorStates.upper,'CLOSED');assert.deepEqual(s.masks.exterior,masks.exterior);assert.equal(s.safe('upper_1F',c.houses.upper.interiorDoor.arrival),false);assert.equal(s.safe('coastal_1F',c.houses.coastal.interiorDoor.arrival),true)});
test('moving gait freezes on pending transfer and resumes idle after rejected source pin',async()=>{const s=make(async()=>({sha256:'bad'}));s.setDoorState('OPEN');s.foot=[...c.houses.upper.exteriorDoor.readFoot];s.move('down');s.move('up');assert.equal(s.moving,true);const oldDistance=s.gaitDistance;s.face('up');assert.equal((await s.action()).reason,'TARGET_SOURCE_PIN_MISMATCH');assert.equal(s.moving,false);assert.equal(s.pose(),9);assert.equal(s.gaitDistance,oldDistance);assert.equal(s.homeId,'upper')});
test('disposed different-home loader cannot mutate scene, home or door states',async()=>{let resolve;const s=make(()=>new Promise(r=>resolve=r));s.setDoorState('OPEN','coastal');at(s,'coastal');const p=s.action();s.dispose();const snap=s.snapshot();resolve({sha256:c.sources.coastal_1F.sha256});assert.equal((await p).reason,'STALE');assert.deepEqual(s.snapshot(),snap)});
